alter table public.news add column if not exists edited_at timestamptz;
drop policy if exists "Admins read all news" on public.news;
create policy "Admins read all news" on public.news for select to authenticated using (public.is_admin());
drop policy if exists "Admins edit news" on public.news;
create policy "Admins edit news" on public.news for update to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists "Admins delete news" on public.news;
create policy "Admins delete news" on public.news for delete to authenticated using (public.is_admin());
grant update, delete on public.news to authenticated;
